(()=>{
if(!document.getElementById('upload-form'))return;const s=Eam.s,params=new URLSearchParams(location.search),equipmentSelect=document.getElementById('upload-equipment'),categorySelect=document.getElementById('upload-category'),input=document.getElementById('upload-file'),inDevice=document.body.dataset.page==='device';let urls=[],page=1,busy=false;
if(inDevice){EamArchiveApi.request("GET","/equipment").then(response=>{for(const e of response.data?.items||[])equipmentSelect.add(new Option(e.code+" / "+e.name,e.id));equipmentSelect.value=params.get("equipment")||"EQ-001";preview();render();}).catch(()=>{});}else for(const e of s.equipmentRecords)equipmentSelect.add(new Option(e.code+" / "+e.name,e.id));equipmentSelect.value=params.get('equipment')||'EQ-001';equipmentSelect.disabled=inDevice;categorySelect.value=params.get('category')||'image';const editable=()=>!busy&&Eam.can(['engineer','supervisor'])&&s.equipmentRecords.find(e=>e.id===equipmentSelect.value)?.lifecycle!=='scrapped';
function preview(){urls.forEach(URL.revokeObjectURL);urls=[];const cat=categorySelect.value;input.accept={image:'.png,.jpg,.jpeg,.webp',document:'.pdf,.txt,.doc,.docx,.xls,.xlsx',model:'.glb,.gltf'}[cat];Eam.text('upload-help',input.accept+' · 本分类每文件'+EamProduct.fileLimits[cat]+'MB内，每批最多10个/合计150MB；全部校验通过才保存');const files=[...input.files],box=document.getElementById('upload-preview');box.replaceChildren();const error=files.length>10?'每批最多10个文件':files.reduce((sum,f)=>sum+f.size,0)>150*1024*1024?'每批合计不超过150MB':files.map(f=>EamProduct.fileError({...f,name:f.name,size:f.size,type:f.type,category:cat})).find(Boolean);Eam.text('upload-error',error||'');document.getElementById('upload-save').disabled=!editable()||!!error;document.getElementById('upload-target').value=files[0]?EamProduct.storageTarget(equipmentSelect.value,cat,'<服务端文件ID>',files[0].name):'eam/equipment/'+equipmentSelect.value+'/'+cat+'/<服务端文件ID>';for(const f of files){const p=document.createElement('p');p.textContent=f.name+' / '+(f.size/1024).toFixed(1)+'KB';box.append(p);if(cat==='image'&&!error){const img=document.createElement('img'),u=URL.createObjectURL(f);urls.push(u);img.src=u;img.alt=f.name;box.append(img);}}if(!files.length)box.textContent='尚未选择文件';}
async function render(){const apiResponse=inDevice?await EamArchiveApi.request("GET","/equipment/"+encodeURIComponent(equipmentSelect.value)+"/archive").catch(()=>null):null;const available=inDevice?(apiResponse?.data?.files||[]):s.assetFiles;const q=Eam.value('file-search').toLowerCase(),cat=Eam.value('file-filter'),status=Eam.value('file-status'),files=available.filter(f=>f.equipmentId===equipmentSelect.value&&f.name.toLowerCase().includes(q)&&(!cat||f.category===cat)&&(!status||f.status===status)),list=document.getElementById('file-list'),pages=Math.max(1,Math.ceil(files.length/5));page=Math.min(page,pages);list.replaceChildren();for(const f of files.slice((page-1)*5,page*5)){Eam.row(list,f.name+' / '+f.revision,EamProduct.label(f.category)+' / '+(f.status==='active'?'有效关联':'已移除')+' / '+(f.localContent?'本机内容已保存，未上传':'仅元数据'));const operations=document.createElement('div');operations.className='actions';for(const [label,action,handler]of [['查看内容','view',()=>EamFileViewer.open([f])],['下载','download',()=>EamFileViewer.download(f)],['移除关联','edit',()=>Eam.confirm('移除设备文件关联',reason=>{if(!Eam.run('removeAssetFile',{id:f.id,reason}))return false;render();window.dispatchEvent(new Event('eam-files-changed'));return true;})]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=!EamProduct.filePermission(s.role,action,f)||(action==='edit'&&!editable());b.onclick=handler;operations.append(b);}list.lastChild.append(operations);}document.getElementById('file-empty').hidden=!!files.length;Eam.text('file-count','共 '+files.length+' 条');Eam.text('file-page-info','第 '+page+' / '+pages+' 页');document.getElementById('file-prev').disabled=page===1;document.getElementById('file-next').disabled=page===pages;}
function clear(){input.value='';preview();}equipmentSelect.onchange=()=>{page=1;clear();render();};categorySelect.onchange=clear;input.onchange=preview;document.getElementById('upload-clear').onclick=clear;for(const id of ['file-search','file-filter','file-status'])document.getElementById(id).addEventListener(id==='file-search'?'input':'change',()=>{page=1;render();});document.getElementById('file-prev').onclick=()=>{page--;render();};document.getElementById('file-next').onclick=()=>{page++;render();};
document.getElementById('upload-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const selected=[...input.files];if(!selected.length||selected.length>10||selected.reduce((sum,f)=>sum+f.size,0)>150*1024*1024){Eam.text('upload-error','请选择1至10个文件，合计不超过150MB');return;}busy=true;document.getElementById('upload-save').setAttribute('aria-busy','true');preview();const version=s.version,actor=s.person,role=s.role,trial=JSON.parse(JSON.stringify(s)),entries=[];let persisted=false;try{for(const f of selected){EamDomain.command(trial,{role:s.role,person:s.person},'saveAssetFile',{equipmentId:equipmentSelect.value,category:categorySelect.value,revision:Eam.value('upload-revision'),name:f.name,size:f.size,type:f.type});const record=trial.assetFiles.at(-1);record.localContent=true;record.localContentKey=crypto.randomUUID();entries.push([record.localContentKey,f]);}await EamFiles.put(entries);persisted=true;if(s.version!==version||s.person!==actor||s.role!==role)throw Error('保存期间业务或人员上下文已变化，未覆盖现有数据，请重试');trial.fileScope=s.fileScope;Object.assign(s,trial);Eam.save();clear();render();window.dispatchEvent(new Event('eam-files-changed'));Eam.message('已保存 '+entries.length+' 个文件的本机内容及设备关联；未上传服务器');}catch(err){if(persisted)await EamFiles.remove(entries.map(x=>x[0]));Eam.text('upload-error',err.message);}finally{busy=false;document.getElementById('upload-save').setAttribute('aria-busy','false');document.getElementById('upload-save').disabled=!editable();render();}};
window.addEventListener('pagehide',()=>urls.forEach(URL.revokeObjectURL));if(inDevice){document.getElementById('asset-manager-close').onclick=()=>document.getElementById('asset-manager-dialog').close();window.EamOpenAssets=category=>{categorySelect.value=category;clear();render();document.getElementById('asset-manager-dialog').showModal();};}preview();render();
})();
